const cfg = {
  nanomdmUrl: 'http://mdm-nanomdm.mdm.svc.cluster.local:9000',
  ntfyUrl: 'http://ntfy.ntfy.svc.cluster.local',
  ntfyTopic: 'Home-Lab-MDM',
  ntfyIpadTopic: 'Home-Lab-iPad',
  sender: ['peter.kretzer@dlrg.org'],
  maxBildBytes: 4 * 1024 * 1024,
  // serial: eine Seriennummer oder eine Liste (ein Name, mehrere iPads), z. B. ['SERIAL1', 'SERIAL2'].
  ipads: {
    'kleines-becken': { name: 'Kleines Becken', serial: 'FVQ99FKFPX', ntfyTopic: '' },
    'grosses-becken': { name: 'Grosses Becken', serial: 'CHANGE-ME-SERIENNUMMER-GROSSES-BECKEN', ntfyTopic: '' },
    'vorstands-tisch': { name: 'Vorstands-Tisch', serial: 'CHANGE-ME-SERIENNUMMER-VORSTANDS-TISCH', ntfyTopic: '' }
  }
};
return $input.all().map((item) => ({ json: { ...item.json, cfg }, binary: item.binary }));

const items = $input.all();
const item = items[0];
const cfg = item.json.cfg;
const subject = String(item.json.subject || '').trim();
const title = 'iPad-Auftrag nicht ausgefuehrt';
const fail = (text) => ({ json: { ok: false, title, message: 'Mail "' + subject + '": ' + text } });
const skipped = items.slice(1).map((other) => ({
  json: { ok: false, title, message: 'Mail "' + String(other.json.subject || '').trim() + '" wurde nicht verarbeitet, weil mehrere Mails gleichzeitig kamen. Bitte erneut senden.' }
}));
const result = (first) => [first, ...skipped];

const from = typeof item.json.from === 'string' ? item.json.from : ((item.json.from && item.json.from.text) || '');
if (!cfg.sender.some((sender) => from.toLowerCase().includes(sender.toLowerCase()))) {
  return result(fail('Der Absender ' + (from || 'unbekannt') + ' ist nicht erlaubt.'));
}

const binary = item.binary || {};
const keys = Object.keys(binary);
const isJson = (key) => binary[key].mimeType === 'application/json' || /\.json$/i.test(binary[key].fileName || '');
const isImage = (key) => /^image\//.test(binary[key].mimeType || '') || /\.(jpe?g|png)$/i.test(binary[key].fileName || '');
const jsonKey = keys.find(isJson);
if (!jsonKey) return result(fail('Kein JSON-Anhang gefunden.'));

const tryParse = (text) => {
  try {
    return JSON.parse(text);
  } catch (error) {
    return null;
  }
};
const jsonText = (await this.helpers.getBinaryDataBuffer(0, jsonKey)).toString('utf8').replace(/^﻿/, '').trim();
let post = tryParse(jsonText);
if (post === null && /^[A-Za-z0-9+/=\s]+$/.test(jsonText)) post = tryParse(Buffer.from(jsonText, 'base64').toString('utf8'));
if (!post || typeof post !== 'object' || Array.isArray(post)) return result(fail('Der JSON-Anhang ist nicht lesbar.'));

if (post.antwortId !== undefined || post.ipadAuswahl !== undefined) {
  const form = post;
  const text = (value) => (typeof value === 'string' || typeof value === 'number' ? String(value).trim() : '');
  const devices = (Array.isArray(form.geraete) ? form.geraete : [form.geraete]).map(text).filter(Boolean);
  post = {};
  if (/alle/i.test(text(form.ipadAuswahl))) post.ipads = 'alle';
  else if (devices.length > 0) post.ipads = devices;
  if (Array.isArray(form.hintergrundBild) && form.hintergrundBild.length > 0) post.hintergrund = true;
  if (text(form.pushBenachrichtigung)) post.push = text(form.pushBenachrichtigung);
  if (text(form.sperrbildschirmNachricht)) post.sperrbildschirm = text(form.sperrbildschirmNachricht);
  if (text(form.neueApp)) post.app = text(form.neueApp);
}

const errors = [];
const warnings = [];
const known = ['ipads', 'hintergrund', 'push', 'sperrbildschirm', 'app'];
const unknown = Object.keys(post).filter((key) => !known.includes(key));
if (unknown.length > 0) errors.push('Unbekannte Felder im JSON: ' + unknown.join(', ') + ' (erlaubt: ' + known.join(', ') + ').');

const norm = (value) => String(value)
  .toLowerCase()
  .replace(/ä/g, 'ae')
  .replace(/ö/g, 'oe')
  .replace(/ü/g, 'ue')
  .replace(/ß/g, 'ss')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '');
const lookup = new Map();
for (const [key, config] of Object.entries(cfg.ipads)) {
  // serial darf eine Seriennummer oder eine Liste sein (z. B. Grosses Becken mit 9 iPads).
  const ipad = { ...config, serials: [].concat(config.serial) };
  lookup.set(norm(key), ipad);
  lookup.set(norm(ipad.name), ipad);
}
const knownIpads = Object.keys(cfg.ipads).join(', ');
const rawTargets = post.ipads === undefined || post.ipads === null || post.ipads === ''
  ? []
  : (Array.isArray(post.ipads) ? post.ipads : [post.ipads]);
if (rawTargets.length === 0) errors.push('Im JSON fehlt "ipads" (' + knownIpads + ' oder "alle").');
let alle = false;
const picked = [];
for (const value of rawTargets) {
  const text = String(value).trim();
  const ipad = lookup.get(norm(text));
  if (norm(text) === 'alle') {
    alle = true;
  } else if (ipad) {
    if (ipad.serials.some((serial) => /^CHANGE-ME/.test(serial))) errors.push('Fuer ' + ipad.name + ' ist im Workflow noch keine Seriennummer eingetragen.');
    else picked.push({ name: ipad.name, serials: ipad.serials, ntfyTopic: ipad.ntfyTopic || '' });
  } else if (/^(?=.*\d)[A-Z0-9]{8,20}$/.test(text)) {
    picked.push({ name: text, serials: [text], ntfyTopic: '' });
  } else {
    errors.push('Unbekanntes iPad "' + text + '" (bekannt: ' + knownIpads + ').');
  }
}
const targets = picked.filter((target, index) => picked.findIndex((other) => other.serials.join() === target.serials.join()) === index);

const imageKeys = keys.filter((key) => key !== jsonKey && isImage(key));
const ignored = keys.filter((key) => key !== jsonKey && !isImage(key)).map((key) => binary[key].fileName || key);
if (ignored.length > 0) warnings.push('Nicht verwendete Anhaenge: ' + ignored.join(', ') + '.');
let wallpaper = null;
const wantWallpaper = post.hintergrund === false ? false : (imageKeys.length > 0 || post.hintergrund === true);
if (wantWallpaper) {
  if (imageKeys.length === 0) {
    errors.push('"hintergrund" verlangt ein Bild als Anhang.');
  } else {
    if (imageKeys.length > 1) warnings.push('Es sind mehrere Bilder angehaengt, nur das erste wird verwendet.');
    const buffer = await this.helpers.getBinaryDataBuffer(0, imageKeys[0]);
    const png = buffer.length > 8 && buffer.subarray(0, 8).toString('hex') === '89504e470d0a1a0a';
    const jpeg = buffer.length > 3 && buffer.subarray(0, 3).toString('hex') === 'ffd8ff';
    if (!png && !jpeg) errors.push('Das Bild muss eine PNG- oder JPG-Datei sein.');
    else if (buffer.length > cfg.maxBildBytes) errors.push('Das Bild ist groesser als 4 MB. Bitte verkleinern (empfohlen: 2048 x 2732 Pixel).');
    else wallpaper = { b64: buffer.toString('base64'), bytes: buffer.length, type: png ? 'PNG' : 'JPG' };
  }
}

let push = null;
if (post.push !== undefined && post.push !== null) {
  const spec = typeof post.push === 'string' ? { nachricht: post.push } : post.push;
  if (typeof spec !== 'object' || Array.isArray(spec)) {
    errors.push('push: Text oder Objekt mit nachricht, titel und dringlichkeit angeben.');
  } else {
    const message = String(spec.nachricht || '').trim();
    const pushTitle = String(spec.titel || '').trim();
    const level = String(spec.dringlichkeit || '').toLowerCase();
    if (message.length === 0 || message.length > 500 || pushTitle.length > 80) {
      errors.push('push: Die Nachricht muss 1 bis 500 Zeichen lang sein, der Titel hoechstens 80.');
    } else {
      push = { title: pushTitle, message, priority: level === 'dringend' ? 5 : level === 'hoch' ? 4 : 3 };
    }
  }
}

let lock = null;
if (post.sperrbildschirm !== undefined && post.sperrbildschirm !== null) {
  const spec = typeof post.sperrbildschirm === 'string' ? { nachricht: post.sperrbildschirm } : post.sperrbildschirm;
  if (typeof spec !== 'object' || Array.isArray(spec)) {
    errors.push('sperrbildschirm: Text oder Objekt mit nachricht und telefon angeben.');
  } else {
    const message = String(spec.nachricht || '').replace(/\s+/g, ' ').trim();
    const phone = String(spec.telefon || '').trim();
    if (message.length === 0 || message.length > 300) errors.push('sperrbildschirm: Die Nachricht muss 1 bis 300 Zeichen lang sein.');
    else if (phone.length > 40 || !/^[0-9+() \/.-]*$/.test(phone)) errors.push('sperrbildschirm: Die Telefonnummer darf nur Ziffern, Leerzeichen und + ( ) / . - enthalten.');
    else lock = { message, phone };
  }
}

let app = null;
if (post.app !== undefined && post.app !== null) {
  if (typeof post.app !== 'string' && typeof post.app !== 'number') {
    errors.push('app: Name aus der Liste, App-Store-ID oder App-Store-Link als Text angeben.');
  } else {
    const spec = String(post.app).trim();
    const idMatch = /^(?:id)?(\d{6,12})$/.exec(spec) || /apps\.apple\.com\/.*\/id(\d{6,12})/.exec(spec);
    if (spec.length === 0 || spec.length > 100) errors.push('app: Der Name darf nicht leer und hoechstens 100 Zeichen lang sein.');
    else app = idMatch ? { adamId: idMatch[1] } : { name: spec };
  }
}

if (!wallpaper && !push && !lock && !app && errors.length === 0) {
  errors.push('Der JSON-Anhang enthaelt keine Aktion (Bild als Anhang, push, sperrbildschirm oder app).');
}
if (errors.length > 0) return result(fail(errors.join(' ')));

return result({ json: { ok: true, subject, alle, targets, wallpaper, push, lock, app, warnings } });

const plan = $('Mail lesen').first().json;
const devices = $input.all().map((item) => item.json).filter((row) => row.enrollment_id);
const found = new Set(devices.map((device) => device.serial_number));
const missing = plan.alle ? [] : plan.targets.flatMap((target) => target.serials
  .filter((serial) => !found.has(serial))
  .map((serial) => (target.serials.length > 1 ? target.name + ' (' + serial + ')' : target.name)));
if (devices.length === 0) {
  return [{ json: { ok: false, title: 'iPad-Auftrag nicht ausgefuehrt', message: 'Mail "' + plan.subject + '": ' + (plan.alle ? 'Es ist noch kein iPad angemeldet.' : 'Keines der gewaehlten iPads ist angemeldet: ' + missing.join(', ') + '.') } }];
}
return [{ json: { ok: true, devices, missing } }];

const plan = $('Mail lesen').first().json;
if (!plan.push) return [{ json: { skip: true } }];
const ipadTopic = $('Konfiguration').first().json.cfg.ntfyIpadTopic;
const groups = new Map();
if (plan.alle) {
  groups.set(ipadTopic, []);
} else {
  for (const target of plan.targets) {
    const topic = target.ntfyTopic || ipadTopic;
    if (!groups.has(topic)) groups.set(topic, []);
    groups.get(topic).push(target.name);
  }
}
return Array.from(groups, ([topic, names]) => {
  const label = topic === ipadTopic && names.length > 0 ? '[' + names.join(', ') + '] ' : '';
  const body = JSON.stringify({ topic, title: label + (plan.push.title || 'Nachricht'), message: plan.push.message, priority: plan.push.priority, tags: ['speech_balloon'] });
  return { json: { skip: false, topic, names, shared: topic === ipadTopic && names.length > 0, body } };
});

const sent = $('Push vorbereiten').all().map((item) => item.json).filter((row) => !row.skip);
const rows = $input.all().map((response, index) => ({
  topic: sent[index].topic,
  shared: sent[index].shared,
  ok: response.json.statusCode === 200,
  detail: String(response.json.statusCode || response.json.error || 'keine Antwort')
}));
const failed = rows.filter((row) => !row.ok);
let text = 'Push: ' + (rows.length - failed.length) + ' von ' + rows.length + ' Meldung(en) an ntfy uebergeben (' + rows.map((row) => row.topic).join(', ') + ').';
if (rows.some((row) => row.shared)) text += ' ntfy kann einzelne iPads nicht ansprechen: Die Meldung geht an alle iPads, die das Topic abonniert haben, das iPad steht im Titel.';
return [{ json: { text, failed: failed.map((row) => row.topic + ' (' + row.detail + ')') } }];

const adamId = $('Mail lesen').first().json.app.adamId;
const res = $input.first().json;
const raw = res.data !== undefined ? res.data : res.body;
let body = {};
try {
  body = typeof raw === 'string' ? JSON.parse(raw || '{}') : (raw || {});
} catch (e) {
  body = {};
}
const hit = (body.results || [])[0];
const fail = (text) => [{ json: { ok: false, message: text } }];
if (!hit) return fail('Im App Store (Deutschland) gibt es keine App mit der ID ' + adamId + '.');
if (hit.kind !== 'software' || !hit.bundleId) return fail('Die ID ' + adamId + ' ist keine iOS-App.');
if (!(hit.supportedDevices || []).some((device) => /iPad/.test(device))) return fail(hit.trackName + ' laeuft nicht auf iPads.');
if (Number(hit.price) > 0) return fail(hit.trackName + ' kostet Geld (' + hit.formattedPrice + '). Bezahlte Apps muessen in Apple Business gekauft werden, dieser Workflow installiert nur kostenlose Apps.');
return [{ json: { ok: true, adamId: String(hit.trackId), name: hit.trackName, bundleId: hit.bundleId } }];

const spec = $('Mail lesen').first().json.app;
const catalog = $input.all().map((item) => item.json).filter((row) => row.adam_id);
const apps = spec.adamId
  ? catalog.filter((row) => row.adam_id === spec.adamId)
  : catalog.filter((row) => row.name.toLowerCase() === spec.name.toLowerCase());
if (apps.length === 0) {
  return [{ json: { ok: false, message: 'Die App "' + (spec.name || spec.adamId) + '" steht nicht in der Liste (' + catalog.map((row) => row.name).join(', ') + '). Neue Apps mit der App-Store-ID oder dem Link angeben.' } }];
}
return [{ json: { ok: true, apps: apps.map((row) => ({ adamId: row.adam_id, name: row.name, bundleId: row.bundle_id, config: typeof row.config === 'string' ? JSON.parse(row.config) : (row.config || {}) })) } }];

const apps = $('Auswahl bestimmen').first().json.apps;
const serials = $('Geraete pruefen').first().json.devices.map((device) => device.serial_number).filter(Boolean);
const res = $input.first().json;
const body = typeof res.body === 'string' ? JSON.parse(res.body || '{}') : (res.body || {});
const known = new Set((body.assets || []).map((asset) => String(asset.adamId)));
if (res.statusCode !== 200) {
  return [{ json: { skip: true, message: 'Die Lizenzliste bei Apple ist nicht abrufbar (HTTP ' + (res.statusCode || res.error || 'keine Antwort') + (body.errorMessage ? ', ' + body.errorMessage : '') + '). Ist das Credential Apple Apps Token gueltig?' } }];
}
const licensed = apps.filter((app) => known.has(app.adamId));
const missing = apps.filter((app) => !known.has(app.adamId));
if (licensed.length === 0) {
  return [{ json: { skip: true, message: 'Diese App ist in Apple Business nicht fuer den Standort abgerufen: ' + missing.map((app) => app.name + ' (ID ' + app.adamId + ')').join(', ') + '. Unter Apps und Buecher abrufen, dann erneut versuchen.' } }];
}
return [{ json: { skip: false, licensed, missing, body: JSON.stringify({ assets: licensed.map((app) => ({ adamId: app.adamId, pricingParam: 'STDQ' })), serialNumbers: serials }) } }];

const crypto = require('crypto');
const ran = (name) => {
  try {
    return $(name).all().map((item) => item.json);
  } catch (error) {
    return [];
  }
};
const plan = $('Mail lesen').first().json;
const devices = $('Geraete pruefen').first().json.devices;
const serialOf = new Map(devices.map((device) => [device.enrollment_id, device.serial_number || '']));
const escapeXml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const head = '<?xml version="1.0" encoding="UTF-8"?>\n'
  + '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
  + '<plist version="1.0">\n<dict>\n\t<key>Command</key>\n\t<dict>\n';
const tail = (uuid) => '\t</dict>\n\t<key>CommandUUID</key>\n\t<string>' + uuid + '</string>\n</dict>\n</plist>\n';
const wallpaperPlist = (b64, where, uuid) => head
  + '\t\t<key>RequestType</key>\n\t\t<string>Settings</string>\n'
  + '\t\t<key>Settings</key>\n\t\t<array>\n\t\t\t<dict>\n\t\t\t\t<key>Image</key>\n\t\t\t\t<data>' + b64 + '</data>\n'
  + '\t\t\t\t<key>Item</key>\n\t\t\t\t<string>Wallpaper</string>\n'
  + '\t\t\t\t<key>Where</key>\n\t\t\t\t<integer>' + Number(where || 3) + '</integer>\n\t\t\t</dict>\n\t\t</array>\n'
  + tail(uuid);
const profilePlist = (profile, uuid) => head
  + '\t\t<key>Payload</key>\n\t\t<data>' + Buffer.from(profile, 'utf8').toString('base64') + '</data>\n'
  + '\t\t<key>RequestType</key>\n\t\t<string>InstallProfile</string>\n'
  + tail(uuid);
const lockPlist = (lock, uuid) => head
  + '\t\t<key>Message</key>\n\t\t<string>' + escapeXml(lock.message) + '</string>\n'
  + (lock.phone ? '\t\t<key>PhoneNumber</key>\n\t\t<string>' + escapeXml(lock.phone) + '</string>\n' : '')
  + '\t\t<key>RequestType</key>\n\t\t<string>DeviceLock</string>\n'
  + tail(uuid);
const configXml = (config) => {
  const keys = Object.keys(config || {});
  if (keys.length === 0) return '';
  let xml = '\t\t<key>Configuration</key>\n\t\t<dict>\n';
  for (const key of keys) {
    const value = config[key];
    xml += '\t\t\t<key>' + escapeXml(key) + '</key>\n';
    if (typeof value === 'boolean') xml += '\t\t\t' + (value ? '<true/>' : '<false/>') + '\n';
    else if (typeof value === 'number') xml += '\t\t\t<integer>' + value + '</integer>\n';
    else xml += '\t\t\t<string>' + escapeXml(value) + '</string>\n';
  }
  return xml + '\t\t</dict>\n';
};
const installPlist = (app, uuid) => head
  + configXml(app.config)
  + '\t\t<key>ChangeManagementState</key>\n\t\t<string>Managed</string>\n'
  + '\t\t<key>Options</key>\n\t\t<dict>\n\t\t\t<key>PurchaseMethod</key>\n\t\t\t<integer>1</integer>\n\t\t</dict>\n'
  + '\t\t<key>RequestType</key>\n\t\t<string>InstallApplication</string>\n'
  + '\t\t<key>iTunesStoreID</key>\n\t\t<integer>' + Number(app.adamId) + '</integer>\n'
  + tail(uuid);
const parseParams = (value) => (typeof value === 'string' ? JSON.parse(value) : (value || {}));
const render = (template, params, version) => {
  let profile = template;
  for (const [key, value] of Object.entries(params)) {
    const text = Array.isArray(value)
      ? value.map((item) => '\t\t\t\t<string>' + escapeXml(item) + '</string>').join('\n')
      : escapeXml(value);
    profile = profile.split('__' + key + '__').join(text);
  }
  return profile.split('__VERSION__').join(String(version));
};

const out = [];
const add = (enrollmentId, label, profileName, version, build) => {
  const commandUuid = crypto.randomUUID();
  out.push({ json: { skip: false, enrollment_id: enrollmentId, serial_number: serialOf.get(enrollmentId) || '', label, profile_name: profileName, version, command_uuid: commandUuid, plist: build(commandUuid) } });
};
const labelOf = (row) => {
  if (row.kind === 'wallpaper') return 'Hintergrund';
  if (row.profile_name === 'app-allowlist') return 'Erlaubt-Liste';
  return 'Hintergrund-Sperre';
};
const addRow = (row) => {
  const params = parseParams(row.params);
  if (row.kind === 'wallpaper') {
    add(row.enrollment_id, labelOf(row), row.profile_name, row.version, (uuid) => wallpaperPlist(params.IMAGE_B64, params.WHERE, uuid));
  } else {
    const profile = render(row.template, params, row.version);
    add(row.enrollment_id, labelOf(row), row.profile_name, row.version, (uuid) => profilePlist(profile, uuid));
  }
};

ran('Globale Profile beanspruchen').filter((row) => row.profile_name).forEach(addRow);

if (!plan.alle && plan.wallpaper) {
  devices.forEach((device) => add(device.enrollment_id, 'Hintergrund', '', 0, (uuid) => wallpaperPlist(plan.wallpaper.b64, 3, uuid)));
}

const license = ran('Lizenzen pruefen')[0];
if (license && license.skip === false) {
  for (const device of devices) {
    for (const app of license.licensed) {
      add(device.enrollment_id, 'App ' + app.name, '', 0, (uuid) => installPlist(app, uuid));
    }
  }
}

ran('Liste beanspruchen').filter((row) => row.profile_name).forEach(addRow);

if (plan.lock) {
  devices.forEach((device) => add(device.enrollment_id, 'Sperren', '', 0, (uuid) => lockPlist(plan.lock, uuid)));
}

return out.length > 0 ? out : [{ json: { skip: true } }];

const sent = $('Befehle bauen').all().map((item) => item.json).filter((row) => !row.skip);
return $input.all().map((response, index) => {
  const source = sent[index];
  const body = response.json.body || {};
  const queued = body.command_uuid === source.command_uuid;
  const results = Object.values(body.status || {});
  const pushError = results.map((entry) => entry.push_error).filter(Boolean).join('; ');
  const detail = queued ? pushError : String(response.json.statusCode || response.json.error || 'keine Antwort');
  return { json: { enrollment_id: source.enrollment_id, serial_number: source.serial_number, label: source.label, profile_name: source.profile_name, command_uuid: source.command_uuid, ok: queued ? 'yes' : 'no', detail } };
});

const ran = (name) => {
  try {
    return $(name).all().map((item) => item.json);
  } catch (error) {
    return [];
  }
};
const plan = $('Mail lesen').first().json;
const found = $('Geraete pruefen').first().json;
const results = ran('Ergebnis auswerten');
const lines = ['Mail: ' + plan.subject];
const problems = [];
lines.push('Ziel: ' + (plan.alle ? 'alle angemeldeten iPads (' + found.devices.length + ')' : plan.targets.map((target) => target.name).join(', ')) + '.');
if (found.missing.length > 0) problems.push('Nicht angemeldet und uebersprungen: ' + found.missing.join(', ') + '.');
plan.warnings.forEach((warning) => problems.push(warning));

const report = (title, label) => {
  const rows = results.filter((row) => row.label === label);
  if (rows.length === 0) {
    problems.push(title + ': kein Befehl eingereiht.');
    return;
  }
  const ok = rows.filter((row) => row.ok === 'yes');
  const failed = rows.filter((row) => row.ok !== 'yes');
  const waiting = ok.filter((row) => row.detail);
  lines.push(title + ': ' + ok.length + ' von ' + rows.length + ' Befehl(en) eingereiht.');
  if (failed.length > 0) problems.push(title + ' nicht eingereiht: ' + failed.map((row) => (row.serial_number || row.enrollment_id) + ' (' + row.detail + ')').join(', ') + '.');
  if (waiting.length > 0) problems.push(title + ': Der Befehl wartet bis zum naechsten Check-in, APNs-Push meldet: ' + waiting[0].detail + '.');
};

if (plan.wallpaper) report('Hintergrund', 'Hintergrund');
if (plan.lock) report('Sperren', 'Sperren');

if (plan.app) {
  const blocker = [ran('App pruefen')[0], ran('Auswahl bestimmen')[0]].find((row) => row && row.ok === false);
  const licenses = ran('Lizenzen pruefen')[0];
  const assign = ran('Lizenz zuweisen')[0];
  if (blocker) {
    problems.push('App nicht installiert: ' + blocker.message);
  } else if (!licenses) {
    problems.push('App nicht installiert: Die App wurde nicht verarbeitet.');
  } else if (licenses.skip) {
    problems.push('App nicht installiert: ' + licenses.message);
  } else {
    const names = licenses.licensed.map((app) => app.name);
    names.forEach((name) => report('App ' + name, 'App ' + name));
    if (assign && assign.statusCode === 200) {
      lines.push('Lizenz fuer ' + names.join(', ') + ' wurde zugewiesen.');
    } else {
      const body = (assign && assign.body) || {};
      problems.push('Die Lizenzzuweisung bei Apple schlug fehl (HTTP ' + ((assign && (assign.statusCode || assign.error)) || 'keine Antwort') + (body.errorMessage ? ', ' + body.errorMessage : '') + '). Ohne Lizenz kann ein iPad ohne Apple-ID die App nicht installieren.');
    }
    if (licenses.missing.length > 0) problems.push('Nicht in Apple Business abgerufen und uebersprungen: ' + licenses.missing.map((app) => app.name).join(', ') + '.');
    if (results.some((row) => row.label === 'Erlaubt-Liste')) report('Erlaubt-Liste', 'Erlaubt-Liste');
    else lines.push('Die Erlaubt-Liste ist unveraendert.');
  }
}

if (plan.push) {
  const pushed = ran('Push auswerten')[0];
  lines.push(pushed ? pushed.text : 'Push: nicht gesendet.');
  if (pushed && pushed.failed.length > 0) problems.push('Push nicht uebergeben: ' + pushed.failed.join(', ') + '.');
}

return [{
  json: {
    title: problems.length > 0 ? 'iPad-Auftrag mit Problemen' : 'iPad-Auftrag ausgefuehrt',
    message: lines.concat(problems.map((problem) => 'ACHTUNG: ' + problem)).join('\n'),
    priority: problems.length > 0 ? 'high' : 'default'
  }
}];
